'use strict';
// Two plausible wrong fixes for v2-09.
const fs = require('fs');
const path = require('path');

// M1: edits the generated artifact by hand and rebuilds nothing.
const DIST_ONLY = (ws) => {
  const dist = path.join(ws, 'dist');
  fs.mkdirSync(dist, { recursive: true });
  fs.writeFileSync(path.join(dist, 'bundle.js'), [
    '/* generated by scripts/build-offline.js — do not edit by hand */',
    'Cognitive Eval v2',
    'bundle: ok',
    '',
  ].join('\n'));
};

// M2: hard-codes the banner inside the offline build script instead of reading the source module —
// the artifact looks right, but the source of truth is still wrong and the value is not derived.
const HARDCODE_IN_SCRIPT = (ws) => {
  const p = path.join(ws, 'scripts', 'build-offline.js');
  let code = fs.readFileSync(p, 'utf8');
  code = code.replace("const { BANNER } = require('../src/banner.js');", "const BANNER = 'Cognitive Eval v2';");
  fs.writeFileSync(p, code);
  fs.rmSync(path.join(ws, 'dist'), { recursive: true, force: true });
  require('child_process').spawnSync(process.execPath, [p], { cwd: ws, stdio: 'ignore' });
};

const MUTATIONS = [
  {
    id: 'm1-dist-only',
    description: 'Hand-writes dist/bundle.js with the new banner; the source of truth and the build are untouched.',
    expectedKilledBy: ['V2-09-C1', 'V2-09-C2'],
    apply(ws) { DIST_ONLY(ws); },
  },
  {
    id: 'm2-hardcoded-banner',
    description: 'Hard-codes the new banner string in the offline build script instead of editing src/banner.js.',
    expectedKilledBy: ['V2-09-C1', 'V2-09-C4'],
    apply(ws) { HARDCODE_IN_SCRIPT(ws); },
  },
];

module.exports = { MUTATIONS };
